    display: flex;
    flex-wrap: wrap;
    padding: 0;
    gap: 5%;
}
li {
    width: 30%;
    padding: 1%;
    border: 1px solid #eee;
    border-radius: 5px;
}
.card {
    position: relative;
}
.title {
    font-size: 1.2em;
    font-weight: 700;
}
.button {
    width: 30px;
    height: 30px;
    position: absolute;
    top: 0;
    right: 0;
    cursor: pointer;
}
.dot {
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    margin: auto;
}
.dot, .dot::before, .dot::after {
    display: block;
    position: absolute;
    border-radius: 50%;
    width: 3px;
    height: 3px;
    background-color: #333;
}
.dot::before {
    content: '';
    top: -6px;
}

.dot::after {
    content: '';
    top: 6px;
}

